function generateWaves() {
	clear();
	drawingContext.shadowOffsetY = 1000 / numWaves * .5;
	drawingContext.shadowBlur = 1000 / numWaves * 0.8;
	drawingContext.shadowColor = shadowCol;

	palette = palettes[colorPalette];
	palette = palette.sort(() => Math.random() - 0.5);

	// colors = [shuffle(colorPalette)[0]]
	colors = [palette[0]]
	for (let i = 1; i < numWaves; i++) {
		prevCol = colors[i - 1];
		newCol = prevCol;
		let _wG_2 = 0; while ((prevCol == newCol) && ++_wG_2 < 20000) { // prevents repeat colors
			newCol = shuffle(palette)[0];
		}
		colors.push(newCol);
	}

	for (let i = numWaves; i > 0; i--) {
		drawShapeCircle(i * height / numWaves, colors[i - 1]);
	}
}

function drawShape_OLD(ypos, swatch) {
	// Draws the wave shapes
	let randomX = [];
	let randomY = [];
	let Ystart = ypos + map(random(), 0, 1, deltaY * -width / numWaves, deltaY * width / numWaves);
	let Yend = ypos + map(random(), 0, 1, deltaY * -width / numWaves, deltaY * width / numWaves);
	for (let i = 0; i < numDivisions; i++) {
		randomX.push(i * width / numDivisions + 0.5 * numDivisions + random(-deltaX * width / numDivisions, deltaX * width / numDivisions));
		randomY.push(ypos + map(random(), 0, 1, deltaY * -width / numWaves, deltaY * width / numWaves));
	}

	// draw solid shape
	noStroke();

	fill(swatch);
	drawingContext.stroke();
	drawingContext.strokeStyle = "rgba(1, 1, 1, 0)";

	beginShape();
	vertex(0, 0);
	if (ypos == height) { // skip drawing quadratic vertexes and draw a background box
		vertex(0, ypos);
		vertex(width, ypos);
	} else {
		vertex(0, Ystart);
		for (let i = 1; i < randomX.length; i += 1) {
			let dx1 = randomX[i];
			let dy1 = randomY[i];
			let dx2 = (randomX[i] + randomX[i + 1]) / 2;
			let dy2 = (randomY[i] + randomY[i + 1]) / 2;
			if (i == randomX.length - 1) {
				dx2 = width;
				dy2 = Yend;
			}
			quadraticVertex(dx1, dy1, dx2, dy2);
		}
	}
	vertex(width, 0);
	endShape(CLOSE);
}

function drawShapeCircle(ypos, swatch, strokecol) {
	// Draws the wave shapes
	let randomX = [];
	let randomY = [];

	let randomXoffset = random(0, width / numDivisions);
	for (let i = 0; i < numDivisions + 2; i++) {
		randomX.push(i * width / numDivisions - randomXoffset);
		randomY.push(ypos + map(random(), 0, 1, deltaY * -width / numWaves, deltaY * width / numWaves));
	}

	// console.log(randomX);
	// console.log(randomY);
	let Ymax = max(randomY);

	// draw solid shape
	strokeWeight(strokeWidth);
	fill(swatch);
	if (colorPalette == "orangebluebrown") { // choose manually set fill/stroke pair
		switch (swatch) { // ["#fe5b14", "#ff9831", "#3131d1", "#cec8b8", "#34bbfb", "#222", "#53372a"]
			case "#3131d1":
				stroke("#34bbfb");
				break;
			case "#34bbfb":
				stroke("#3131d1");
				break;
			case "#fe5b14":
				stroke("#ff9831");
				break;
			case "#ff9831":
				stroke("#fe5b14");
				break;
			case "#cec8b8":
				stroke("#222");
				break;
			case "#222":
				stroke("#cec8b8");
				break;
			case "#53372a":
				stroke("#cec8b8");
				break;
		}
	} else { // randomly select a different stroke color
		let remainingcols = [...palette];
		remainingcols.splice(remainingcols.indexOf(swatch), 1); // remove already chosen color
		stroke(shuffle(remainingcols)[0]); // randomly choose a remaining color
	}
	if ((colorPalette == "sunset" || colorPalette == "pastel" || colorPalette == "cyber") && random() < 0.1) {
		fill("#222");
	}


	beginShape();
	vertex(-strokeWidth, -strokeWidth);
	if (ypos == height) { // skip drawing quadratic vertexes and draw a background box
		vertex(-strokeWidth, height + strokeWidth);
		vertex(width + strokeWidth, height + strokeWidth);
	} else {
		vertex(randomX[0], randomY[0]);
		for (let i = 1; i < randomX.length - 1; i++) {
			let dx1 = randomX[i];
			let dy1 = randomY[i];
			let dx2 = (randomX[i] + randomX[i + 1]) / 2;
			let dy2 = (randomY[i] + randomY[i + 1]) / 2;
			if (mode == "waves&circles") {
				if (dy1 == Ymax || random() < probCircles) {
					let r = random(height / numWaves,  height / numWaves * circleRadiusMax);
					circle(dx1, dy1 + r / 2 * circleOffset, r);
				}
			}
			quadraticVertex(dx1, dy1, dx2, dy2);
		}
	}
	let l = randomX.length;
	vertex(randomX[l - 1], randomY[l - 1]);
	vertex(randomX[l - 1], -strokeWidth);
	endShape(CLOSE);
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
